('wb-eg','World Bank procurement notices — Egypt','إعلانات مشتريات البنك الدولي — مصر','tender_gov','eg','en','json','https://search.worldbank.org/api/v2/procnotices?format=json&rows=60&os=0&srt=submission_date&order=desc&fl=id,notice_type,noticedate,submission_deadline_date,project_ctry_name,project_id,project_name,bid_reference_no,bid_description,procurement_group,procurement_method_code,procurement_method_name,contact_organization&project_ctry_code=EG','GET',NULL,'{"items":"procnotices","fields":{"ext_id":"id","title":"bid_description|project_name","url":{"tpl":"https://projects.worldbank.org/en/projects-operations/procurement-detail/{id}"},"published":"noticedate","deadline":"submission_deadline_date","entity":"contact_organization","country":"project_ctry_name","summary":{"join":["project_name","notice_type","procurement_method_name"],"sep":" — "},"notice_type":"notice_type","proc_group":"procurement_group","proc_method":"procurement_method_code"},"kind_map":{"field":"notice_type","map":{"Contract Award":"project_news","General Procurement Notice":"project"},"default":"tender_gov"},"rfq_methods":["RFQ"],"market_from":"country","max_age_days":45}','A',1,1,'World Bank Search API, public, no key; World Bank terms of use for datasets (CC BY 4.0). robots: search.worldbank.org/robots.txt 404 (no rules).',3,'https://projects.worldbank.org/en/projects-operations/procurement?srce=both&countrycode_exact=EG',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('wb-arab','World Bank procurement notices — Arab countries','إعلانات مشتريات البنك الدولي — الدول العربية','tender_gov','intl','en','json','https://search.worldbank.org/api/v2/procnotices?format=json&rows=60&os=0&srt=submission_date&order=desc&fl=id,notice_type,noticedate,submission_deadline_date,project_ctry_name,project_id,project_name,bid_reference_no,bid_description,procurement_group,procurement_method_code,procurement_method_name,contact_organization&project_ctry_code=MA%5EJO%5EIQ%5ETN%5ELB%5EYE%5EDZ%5ELY%5EDJ%5EPS%5EMR%5ESO','GET',NULL,'{"items":"procnotices","fields":{"ext_id":"id","title":"bid_description|project_name","url":{"tpl":"https://projects.worldbank.org/en/projects-operations/procurement-detail/{id}"},"published":"noticedate","deadline":"submission_deadline_date","entity":"contact_organization","country":"project_ctry_name","summary":{"join":["project_name","notice_type","procurement_method_name"],"sep":" — "},"notice_type":"notice_type","proc_group":"procurement_group","proc_method":"procurement_method_code"},"kind_map":{"field":"notice_type","map":{"Contract Award":"project_news","General Procurement Notice":"project"},"default":"tender_gov"},"rfq_methods":["RFQ"],"market_from":"country","max_age_days":45}','B',1,1,'World Bank Search API, public, no key (CC BY 4.0).',3,'https://projects.worldbank.org/en/projects-operations/procurement',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('wb-africa','World Bank procurement notices — Africa','إعلانات مشتريات البنك الدولي — أفريقيا','tender_gov','africa','en','json','https://search.worldbank.org/api/v2/procnotices?format=json&rows=60&os=0&srt=submission_date&order=desc&fl=id,notice_type,noticedate,submission_deadline_date,project_ctry_name,project_id,project_name,bid_reference_no,bid_description,procurement_group,procurement_method_code,procurement_method_name,contact_organization&project_ctry_code=KE%5ENG%5EET%5EGH%5ETZ%5EUG%5ERW%5ESN%5ECI%5EZA%5ECM%5EAO%5EMZ%5EZM%5EMW%5ESD%5ESS%5ECD','GET',NULL,'{"items":"procnotices","fields":{"ext_id":"id","title":"bid_description|project_name","url":{"tpl":"https://projects.worldbank.org/en/projects-operations/procurement-detail/{id}"},"published":"noticedate","deadline":"submission_deadline_date","entity":"contact_organization","country":"project_ctry_name","summary":{"join":["project_name","notice_type","procurement_method_name"],"sep":" — "},"notice_type":"notice_type","proc_group":"procurement_group","proc_method":"procurement_method_code"},"kind_map":{"field":"notice_type","map":{"Contract Award":"project_news","General Procurement Notice":"project"},"default":"tender_gov"},"rfq_methods":["RFQ"],"market_from":"country","max_age_days":45}','B',1,1,'World Bank Search API, public, no key (CC BY 4.0).',3,'https://projects.worldbank.org/en/projects-operations/procurement',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ted-mena-africa','EU TED — notices in Egypt, the Arab world & Africa','منصة TED الأوروبية — مناقصات في مصر والدول العربية وأفريقيا','tender_gov','intl','en','json','https://api.ted.europa.eu/v3/notices/search','POST','{"query": "publication-date>={{date-14:compact}} AND (buyer-country IN (EGY SAU ARE QAT KWT OMN BHR JOR IRQ MAR TUN DZA LBY LBN KEN NGA ETH GHA TZA UGA SEN CIV ZAF) OR place-of-performance IN (EGY SAU ARE MAR TUN DZA JOR IRQ LBY KEN ETH NGA))", "fields": ["publication-number", "notice-title", "buyer-name", "buyer-country", "deadline-receipt-tender-date-lot", "classification-cpv", "publication-date", "notice-type", "estimated-value-lot", "estimated-value-cur-lot"], "limit": 50, "page": 1, "scope": "ACTIVE", "paginationMode": "PAGE_NUMBER"}','{"items":"notices","fields":{"ext_id":"publication-number","title":"notice-title.eng|notice-title.fra|notice-title.*","url":{"tpl":"https://ted.europa.eu/en/notice/-/detail/{publication-number}"},"published":"publication-date.0|publication-date","deadline":"deadline-receipt-tender-date-lot.0","entity":"buyer-name.eng.0|buyer-name.fra.0|buyer-name.*.0","country":"buyer-country.0","cpv":"classification-cpv","value":"estimated-value-lot.0","currency":"estimated-value-cur-lot.0"},"market_from":"country","max_age_days":30}','B',1,1,'TED API v3 anonymous search (EU Publications Office); TED data reuse is free (Decision 2011/833/EU).',3,'https://ted.europa.eu/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ted-eu-supplies','EU TED — supply tenders in sectors Egyptian factories export','منصة TED الأوروبية — مناقصات توريد في قطاعات التصدير المصرية','tender_gov','eu','en','json','https://api.ted.europa.eu/v3/notices/search','POST','{"query": "publication-date>={{date-2:compact}} AND notice-type IN (cn-standard) AND contract-nature IN (supplies) AND classification-cpv IN (15000000 18000000 19000000 24000000 31000000 33000000 39000000 44000000 03000000)", "fields": ["publication-number", "notice-title", "buyer-name", "buyer-country", "deadline-receipt-tender-date-lot", "classification-cpv", "publication-date", "notice-type", "estimated-value-lot", "estimated-value-cur-lot"], "limit": 60, "page": 1, "scope": "ACTIVE", "paginationMode": "PAGE_NUMBER"}','{"items":"notices","fields":{"ext_id":"publication-number","title":"notice-title.eng|notice-title.fra|notice-title.*","url":{"tpl":"https://ted.europa.eu/en/notice/-/detail/{publication-number}"},"published":"publication-date.0|publication-date","deadline":"deadline-receipt-tender-date-lot.0","entity":"buyer-name.eng.0|buyer-name.fra.0|buyer-name.*.0","country":"buyer-country.0","cpv":"classification-cpv","value":"estimated-value-lot.0","currency":"estimated-value-cur-lot.0"},"market_from":"country","max_age_days":7}','B',1,1,'TED API v3 anonymous search; free reuse.',3,'https://ted.europa.eu/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('wb-projects-v3','World Bank Projects API v3 — Africa & MENA pipeline projects','البنك الدولي — المشروعات المرتقبة في أفريقيا والشرق الأوسط','project','intl','en','json','https://search.worldbank.org/api/v3/projects?format=json&rows=100&os=0&status_exact=Pipeline%5EActive&regionname_exact=Eastern%20and%20Southern%20Africa%5EWestern%20and%20Central%20Africa%5EMiddle%20East%2C%20North%20Africa%2C%20Afghanistan%2C%20and%20Pakistan&srt=boardapprovaldate&order=desc&fl=id,project_name,boardapprovaldate,countryshortname,countrycode,regionname,status,totalamt,borrower,impagency,project_abstract','GET',NULL,'{"adapter":"json","accept":"application/json","pages":1,"market_from":"market_hint","exclude_countries":["EG"],"max_age_days":400}','C',1,1,'World Bank Search API v3, public, no key; CC BY 4.0. robots.txt: 404. Egypt rows are left to wb-projects-eg. Region names are the 2025+ ones ("Middle East, North Africa, Afghanistan, and Pakistan").',2,'https://projects.worldbank.org/en/projects-operations/projects-home',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('wb-financesone-contract-awards','World Bank Finances One — contract awards (DS00005): Egypt and Egyptian suppliers','البنك الدولي — ترسيات العقود في مصر وللموردين المصريين','project_news','intl','en','json','https://datacatalogapi.worldbank.org/dexapps/fone/api/apiservice?datasetId=DS00005&resourceId=RS00005&type=json&top=100&skip=0&filter=(borrower_country_code=''EG''%20or%20supplier_country_code=''EG'')%20and%20contract_signing_date%3E%3D''{{date-180}}''','GET',NULL,'{"adapter":"json","accept":"application/json","pages":1,"market_from":"market_hint","max_age_days":200}','C',1,1,'World Bank open data (CC BY 4.0), no key; robots.txt: 404. Awards lag signing by weeks → rolling 180-day window on contract_signing_date. Suppliers are named only when clearly a company; individual consultants and personal names are never stored.',2,'https://financesone.worldbank.org/contract-awards-in-investment-project-financing/DS00005',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ebrd-ecepp','EBRD – ECEPP project procurement notices','البنك الأوروبي لإعادة الإعمار والتنمية – إعلانات مشتريات المشروعات (ECEPP)','tender_gov','intl','en','adapter','https://ecepp.ebrd.com/delta/noticeSearchResults.html','GET',NULL,'{"adapter":"bigtables","market_from":"market_key","kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}},"max_age_days":60}','C',1,1,'Public list, no login (bid documents need a free ECEPP supplier account). robots.txt ''User-agent: * Disallow:'' (re-checked 2026-11-18). One ~3.9 MB fetch a day; keeps open tenders, GPNs ≤ 60 days (project) and contract awards ≤ 30 days (project_news); country prefix → market (Egypt → eg).',3,'https://ecepp.ebrd.com/delta/noticeSearchResults.html',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('isdb-tenders','Islamic Development Bank – Project procurement tenders','البنك الإسلامي للتنمية – مناقصات المشروعات','tender_gov','intl','en','adapter','https://www.isdb.org/project-procurement/tenders?page={{page0}}','GET',NULL,'{"adapter":"htmllists","pages":5,"filter_re":"^status:active\\b","market_from":"market_key","kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}},"accept":"text/html,application/xhtml+xml;q=0.9,*/*;q=0.5"}','C',1,1,'robots.txt allows /project-procurement/ (disallows /node/, /user/, /taxonomy/, /search/). IsDB terms (isdb.org/terms-conditions) allow reproducing or translating a limited extract free of charge if IsDB (www.isdb.org) is cited as the source and translations state they are not official IsDB translations; stored: title, notice type, country, closing date, official link. The list ignores ?status=, so pages 0–4 are read (an empty page ends the paging) and only Active notices are kept (mapping.filter_re).',2,'https://www.isdb.org/project-procurement/tenders',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('za-etenders-ocds','South Africa — National Treasury eTenders OCDS API','جنوب أفريقيا — بوابة المناقصات الحكومية (الخزانة الوطنية)','tender_gov','africa:za','en','json','https://ocds-api.etenders.gov.za/api/OCDSReleases?PageNumber={{page}}&PageSize=100&dateFrom={{date-2}}&dateTo={{date-1}}','GET',NULL,'{"adapter":"json","accept":"application/json","pages":2,"kind_map":{"field":"buyer_type","map":{"semi":"tender_semi","private":"tender_private"},"default":"tender_gov"},"rfq_methods":["Request for Quotation"]}','C',1,1,'Open Data Commons PDDL 1.0 (public domain); robots.txt: 404. The API answers HTTP 500 when dateTo is today or equals dateFrom, and for PageSize > 100 → window = the two previous days. Link = the official tender advert document.',2,'https://www.etenders.gov.za/Home/opportunities?id=1',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ke-ppip','Kenya — Public Procurement Information Portal (PPIP) active tenders','كينيا — بوابة معلومات المشتريات العامة (مناقصات سارية)','tender_gov','africa:ke','en','json','https://tenders.go.ke/api/active-tenders?sortby=published_at&order=desc&perpage=50&page={{page}}','GET',NULL,'{"adapter":"json","accept":"application/json","pages":2,"kind_map":{"field":"buyer_type","map":{"semi":"tender_semi","private":"tender_private"},"default":"tender_gov"},"rfq_methods":["Request for Quotation","Request for Quotations"]}','C',1,1,'robots.txt: User-agent: * Disallow: (all allowed). API of the public portal (rate limit 60 req/min per IP); default order is by closing date, so the portal''s own sortby/order/perpage parameters are used (newest first). Officials'' personal data in created_by / team_members / subscribers is never read; disposals of assets are skipped.',2,'https://tenders.go.ke/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ug-gpp','Uganda — Government Procurement Portal (PPDA) bid invitations','أوغندا — بوابة المشتريات الحكومية (دعوات العطاءات)','tender_gov','africa:ug','en','json','https://cdn.ppda.go.ug/api/bid-invitations?page={{page}}','GET',NULL,'{"adapter":"json","accept":"application/json","pages":2,"kind_map":{"field":"buyer_type","map":{"semi":"tender_semi","private":"tender_private"},"default":"tender_gov"},"rfq_methods":["Request for Quotations/Proposals (RFQ/P)"]}','C',1,1,'robots.txt: User-agent: * Disallow: (all allowed). API of the public portal; list is ordered by bid deadline (latest first), so 2 pages cover the open invitations. initiated_by (an official''s name) is never read.',2,'https://gpp.ppda.go.ug/public/bid-invitations',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('gh-ghaneps','Ghana – GHANEPS e-procurement: current calls for tender','غانا – منظومة المشتريات الإلكترونية GHANEPS: المناقصات المطروحة','tender_gov','africa:gh','en','adapter','https://www.ghaneps.gov.gh/epps/quickSearchAction.do?d-3680175-p={{page}}&searchSelect=1&T01_ps=50','GET',NULL,'{"adapter":"htmllists","pages":2,"kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}},"accept":"text/html,application/xhtml+xml;q=0.9,*/*;q=0.5"}','C',1,1,'Public quick-search list and notice pages (no login). robots.txt answers a 302 to the home page, so there are no robots rules; the portal publishes no terms of use. 50 rows per page through the site''s own page-size control (T01_ps), 2 pages a day, newest first; only calls in «Bid Submission» are kept. One connection reset seen on 2026-11-18 (the engine retries once).',2,'https://www.ghaneps.gov.gh/epps/quickSearchAction.do?searchSelect=1',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ci-dgmp','Côte d''Ivoire – DGMP marchés publics: avis d''appels d''offres','كوت ديفوار – المديرية العامة للصفقات العمومية (DGMP): إعلانات طلب العروض','tender_gov','africa:ci','fr','adapter','https://www.marchespublics.ci/appel_offre','GET',NULL,'{"adapter":"htmllists","kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}},"accept":"text/html,application/xhtml+xml;q=0.9,*/*;q=0.5"}','C',1,1,'robots.txt 404 (no rules); no terms of use on the portal. One public table of ~1,456 notices (1.3 MB) without per-notice pages: each item links to the official list with an inert ?ao=<Numéro AO> (the server ignores it, verified) so links stay distinct, and the reference is quoted in the excerpt. Awards (/avis_attribution) are not read.',2,'https://www.marchespublics.ci/appel_offre',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ng-bpp-adverts','Nigeria – Bureau of Public Procurement adverts page',NULL,'tender_gov','intl','en','html','https://bpp.gov.ng/advertisement/','GET',NULL,'{}','C',0,1,'WordPress site; /feed/ exists but last item Oct-2025 (stale).',2,'https://bpp.gov.ng/advertisement/',1,'no open machine-readable access (verified_partial) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('comesa-news','COMESA Secretariat news feed',NULL,'news','africa','en','rss','https://www.comesa.int/feed/','GET',NULL,'{}','B',1,1,'RSS published for syndication; store headline + short snippet + link back only (content is copyrighted).',1,'https://www.comesa.int/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
