('hwmia','How We Made It In Africa',NULL,'news','africa','en','rss','https://www.howwemadeitinafrica.com/feed','GET',NULL,'{}','B',1,1,'robots.txt disallows only /action/, /publish, /sign-in. RSS published for syndication; store headline + short snippet + link back only (content is copyrighted).',1,'https://www.howwemadeitinafrica.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('esi-africa','ESI Africa (power & energy)',NULL,'project_news','africa','en','rss','https://www.esi-africa.com/feed/','GET',NULL,'{}','B',1,1,'robots.txt: Disallow /wp-admin/ only. RSS published for syndication; store headline + short snippet + link back only (content is copyrighted).',1,'https://www.esi-africa.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
