('africanews','Africanews RSS',NULL,'news','africa','en','rss','https://www.africanews.com/feed/rss','GET',NULL,'{}','B',1,1,'RSS published for syndication; store headline + short snippet + link back only (content is copyrighted).',1,'https://www.africanews.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('afdb-procurement','African Development Bank – procurement notices / RSS / MapAfrica',NULL,'tender_gov','intl','en','html','https://www.afdb.org/en/projects-and-operations/procurement','GET',NULL,'{}','C',0,1,'Every afdb.org path (incl. robots.txt, rss.xml) and mapafrica.afdb.org returned a Cloudflare managed challenge (403 ''Just a moment...''); projectsportal.afdb.org failed (CONNECT 502). Not automatable without AfDB permission.',2,'https://www.afdb.org/en/projects-and-operations/procurement',1,'no open machine-readable access (blocked) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('iati-datastore','IATI Datastore API (AfDB, WB, IsDB, EBRD, EIB, UN activities)',NULL,'project','intl','en','html','https://api.iatistandard.org/datastore/activity/select?q=reporting_org_ref:46002&rows=100','GET',NULL,'{}','C',0,1,'401 ''missing subscription key'' without key. Free registration at developer.iatistandard.org; data is open (publisher licences mostly CC BY / ODC).',2,'https://api.iatistandard.org/datastore/activity/select?q=reporting_org_ref:46002&rows=100',1,'no open machine-readable access (unverified_needs_key) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ungm','UN Global Marketplace (UNGM) – public notices (covers UNDP, UNOPS, UNICEF, WFP, FAO, UNIDO, UNHCR…)',NULL,'tender_gov','intl','en','html','https://www.ungm.org/Public/Notice','GET',NULL,'{}','C',0,1,'Public page reachable; robots.txt does not disallow /Public/Notice (disallows /Public/Notice/DownloadAllDocuments). But notices load via JS POST /Public/Notice/Search that requires a session cookie + anti-forgery token – not an open API; not used.',2,'https://www.ungm.org/Public/Notice',1,'no open machine-readable access (unverified) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
