INSERT INTO intel_sources (id,name,name_ar,kind,market,lang,parser,endpoint,method,body,mapping,schedule,enabled,robots_ok,terms_note,official,homepage,listed,disabled_reason,created_at,updated_at) VALUES
('gh-ppa-tenders','Ghana PPA tender portal',NULL,'tender_gov','intl','en','html','https://tenders.ppa.gov.gh/','GET',NULL,'{}','C',0,1,'Connection reset on 2 attempts – use GHANEPS (verified) instead.',2,'https://tenders.ppa.gov.gh/',1,'no open machine-readable access (unverified) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ma-marchespublics','Maroc – Portail marocain des marchés publics',NULL,'tender_gov','intl','en','html','https://www.marchespublics.gov.ma/index.php?page=entreprise.EntrepriseAdvancedSearch&AllCons&searchAnnCons','GET',NULL,'{}','C',0,1,'robots.txt returned 403; homepage reset; search page loads but results need a PRADO form POST (stateful). Not suitable for unattended Worker without permission.',2,'https://www.marchespublics.gov.ma/index.php?page=entreprise.EntrepriseAdvancedSearch&AllCons&searchAnnCons',1,'no open machine-readable access (unverified) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('om-esnaad-public-dash','Oman Tender Board – Esnaad public dashboard (new tenders)','مجلس المناقصات العُماني – منصة إسناد: المناقصات المطروحة','tender_gov','om','ar','adapter','https://etendering.tenderboard.gov.om/product/publicDash?viewFlag=NewTenders&pageNo={{page}}','GET',NULL,'{"adapter":"bigtables","pages":2,"kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}}}','B',1,1,'Public list, no login; robots.txt 404 (no rules). The tender view needs a session (''Security Page''), so items link to the public dashboard (&tenderNo=<id> is ignored by the server and keeps links distinct). ~2,150 floated tenders, 50 per page newest first: 2 pages every 6 h. The list has no publication date. Government companies → semi-government; direct-assignment rows skipped.',2,'https://etendering.tenderboard.gov.om/product/publicDash?viewFlag=NewTenders',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('bh-tenderboard-published','Bahrain Tender Board – published tenders (JSON web service)','مجلس المناقصات والمزايدات البحريني – المناقصات المطروحة','tender_gov','bh','en','html','https://www.tenderboard.gov.bh/Templates/TenderBoardWebService.aspx/GetCurrentPublicTenderByPage','GET',NULL,'{}','C',0,1,'robots.txt not served (soft 404 HTML). Terms of Use: contents ''shall not be reproduced, republished ... without the prior written permission of the Tender Board'' -> store only facts (no., subject, authority, dates) + deep link; request written permission before republishing. Includes semi-gov buyers',2,'https://www.tenderboard.gov.bh/Templates/TenderBoardWebService.aspx/GetCurrentPublicTenderByPage',1,'Bahrain Tender Board terms forbid republishing without written permission — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ly-noc-tenders','National Oil Corporation (Libya) – tenders','المؤسسة الوطنية للنفط الليبية – المناقصات','tender_semi','ly','en','adapter','https://noc.ly/en/tenders/','GET',NULL,'{"adapter":"htmllists","kind_map":{"field":"kind_hint","map":{"semi":"tender_semi","rfq":"rfq","project":"project","award":"project_news"}},"accept":"text/html,application/xhtml+xml;q=0.9,*/*;q=0.5"}','C',0,1,'robots.txt allows / for all bots except named AI crawlers (Content-Signal: search=yes, ai-train=no, use=reference). Terms of Use (noc.ly/en/terms-of-use/): «You may not reproduce, modify, distribute, or republish any part of the Website without our prior written consent». Page 1 of /en/tenders/ (10 newest rows) answers 200 to the bot; /en/tenders/page/2/, notice pages and the WordPress feed answer a Cloudflare challenge (403).',2,'https://noc.ly/en/tenders/',1,'NOC''s Terms of Use forbid reproducing or republishing any part of noc.ly without its prior written consent; list pages after the first, notice pages and the feed are behind a Cloudflare bot check. Adapter ready, to be enabled once NOC consents.','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('argaam-ar-main','Argaam – main news (Arabic RSS)','أرقام – الأخبار الرئيسية','news','sa','ar','rss','https://www.argaam.com/ar/rss/ho-main-news?sectionid=1523','GET',NULL,'{}','B',1,1,'robots: * allowed except /bf/. Feed directory at /ar/rss and /en/rss. Terms page not located (guessed /en/content/terms = 404) -> link-out + own short summary only. Avoid /ar/rss/companies (stale, 2022 items).',1,'https://www.argaam.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('argaam-en-disclosures','Argaam – company disclosures (English RSS; contract awards of listed Saudi firms)','أرقام – إفصاحات الشركات','project_news','sa','en','rss','https://www.argaam.com/en/rss/ho-company-disclosures?sectionid=244','GET',NULL,'{}','B',1,1,'Same as argaam-ar-main. Useful signal: ''signs SAR xxM contract/deal with ...'' = buyer demand.',1,'https://www.argaam.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('saudigazette-business','Saudi Gazette – Business (RSS)','سعودي جازيت – الأعمال','project_news','sa','en','rss','https://saudigazette.com.sa/rssFeed/73','GET',NULL,'{}','B',1,1,'Site says RSS ''completely free''. robots: * allowed (Crawl-delay 10). Section ids via https://saudigazette.com.sa/api/pb/sections?widget_id=23901 (73=BUSINESS, 74=SAUDI ARABIA; 46=Economy is empty).',1,'https://saudigazette.com.sa/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('aleqt-news-sitemap','Al Eqtisadiah (aleqt.com) – Google-News sitemap','الاقتصادية – خريطة الأخبار','news','sa','ar','sitemap','https://www.aleqt.com/sitemaps/newsSitemap.xml','GET',NULL,'{}','B',1,1,'No RSS (/rss, /rss.xml, /feed = 404). robots.txt: User-agent * Allow: / and lists this news sitemap. Titles only -> AI summary from title; link out.',1,'https://www.aleqt.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('gulfnews-business','Gulf News – Business (RSS)','جلف نيوز – الأعمال','news','ae','en','rss','https://gulfnews.com/api/v1/collections/business.rss','GET',NULL,'{}','B',1,1,'robots: * allowed for this path (disallows search/ajax). Quintype collection feed; many ''corporate-news'' (press releases) -> lower relevance.',1,'https://gulfnews.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('khaleejtimes-business','Khaleej Times – Business (RSS)','خليج تايمز – الأعمال','news','ae','en','rss','https://www.khaleejtimes.com/api/v1/collections/business.rss','GET',NULL,'{}','B',1,1,'Feed link published in the site''s own <head>. robots: * not restricted for /api/v1/collections (only bot-specific rules).',1,'https://www.khaleejtimes.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('cbnme','Construction Business News Middle East (RSS)','أخبار أعمال البناء – الشرق الأوسط','project_news','gcc','en','rss','https://www.cbnme.com/feed/','GET',NULL,'{"ai_title_only":true}','B',1,1,'robots: * Allow: /, Content-Signal: search=yes, ai-train=no (+ ''use=reference''); blocks ClaudeBot/CCBot etc. by name. Our use = reference + link-out; never train; AI summary only from title+feed excerpt.',1,'https://www.cbnme.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
