('iraq-business-news','Iraq Business News (RSS)','أخبار الأعمال العراقية','project_news','iq','en','rss','https://www.iraq-businessnews.com/feed/','GET',NULL,'{}','B',1,1,'robots: * allowed (only /wp-admin/). Best machine-readable proxy for Iraqi projects/tenders (no central Iraqi e-procurement portal found).',1,'https://www.iraq-businessnews.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('libya-herald','Libya Herald (RSS)','ليبيا هيرالد','news','ly','en','rss','https://libyaherald.com/feed/','GET',NULL,'{}','B',1,1,'robots not checked (timebox). Category feed /category/business/feed/ redirects (302) -> use main feed + keyword filter.',1,'https://libyaherald.com/',1,NULL,'2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('sa-etimad','Etimad – Saudi government tenders (visitor list)','منصة اعتماد – المنافسات الحكومية','tender_gov','sa','en','html','https://tenders.etimad.sa/Tender/AllTendersForVisitor','GET',NULL,'{}','C',0,1,'F5 BIG-IP ASM bot defence: returns ''This question is for testing whether you are a human visitor'' CAPTCHA page (also on /Tender/AllSupplierTendersForVisitorAsync). No public API/RSS. Do not scrape; ask LCGPA/Etimad for a data feed or cover via news (Argaam disclosures, Saudi Gazette, Aleqt). Saudi o',2,'https://tenders.etimad.sa/Tender/AllTendersForVisitor',1,'no open machine-readable access (blocked) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ae-dubai-esupply','Dubai eSupply – current opportunities (JAGGAER)','دبي للمشتريات الإلكترونية','tender_gov','ae','en','html','https://esupply.dubai.gov.ae/esop/guest/go/public/opportunity/current','GET',NULL,'{}','C',0,1,'JAGGAER platform: first hit 401, then redirects non-browser clients to browserNotSupported.jsp. Needs a real browser (not allowed/not possible from a Worker). robots.txt exists (29 bytes). Unverified listing.',2,'https://esupply.dubai.gov.ae/esop/guest/go/public/opportunity/current',1,'no open machine-readable access (blocked) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ae-adgpg','Abu Dhabi Government Procurement Gate (ADGPG) – public tenders','بوابة أبوظبي للمشتريات الحكومية','tender_gov','ae','en','html','https://www.adgpg.gov.ae/en/For-Suppliers/Public-Tenders','GET',NULL,'{}','C',0,1,'Guessed listing URL = 404 (site is Sitecore ''AlMaqtaa'' theme); correct list URL not found in the timebox. robots.txt reachable (229 bytes).',2,'https://www.adgpg.gov.ae/en/For-Suppliers/Public-Tenders',1,'no open machine-readable access (unverified) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
('ae-dewa','DEWA – list of tender documents','هيئة كهرباء ومياه دبي – المناقصات','tender_semi','ae','en','html','https://www.dewa.gov.ae/en/supplier/services/list-of-tender-documents','GET',NULL,'{}','C',0,1,'HTTP 403 (WAF) to non-browser clients.',2,'https://www.dewa.gov.ae/en/supplier/services/list-of-tender-documents',1,'no open machine-readable access (blocked) — official link only','2026-11-18T18:20:47.742Z','2026-11-18T18:20:47.742Z'),
